/**
 * Render prompt với các biến do người dùng nhập hoặc từ hồ sơ cơ quan
 */
export function renderPrompt(
  template: PromptTemplate,
  variableValues: Record<string, string>,
  orgProfile?: OrgProfile
): string {
  let result = template.templateText;

  // Lấy giá trị cơ quan mặc định hoặc từ profile
  const tenXa = variableValues['ten_xa'] || orgProfile?.ten_xa_phuong || 'Trường Đại học Hùng Vương';
  const tenTinh = variableValues['ten_tinh'] || orgProfile?.ten_tinh_tp || 'Tỉnh Phú Thọ';
  const diaDanh = variableValues['dia_danh'] || orgProfile?.dia_danh || 'Phú Thọ';
  const tenCoQuan = variableValues['co_quan_ban_hanh'] || orgProfile?.ten_co_quan || 'TRƯỜNG ĐẠI HỌC HÙNG VƯƠNG';
  const tenXaUppercase = tenXa.toUpperCase().replace(/^XÃ\s+|^PHƯỜNG\s+|^THỊ TRẤN\s+/i, '');

  result = result.replace(/\{\{ten_xa\}\}/g, tenXa);
  result = result.replace(/\{\{ten_xa_uppercase\}\}/g, tenXaUppercase);
  result = result.replace(/\{\{ten_tinh\}\}/g, tenTinh);
  result = result.replace(/\{\{dia_danh\}\}/g, diaDanh);
  result = result.replace(/\{\{ten_co_quan\}\}/g, tenCoQuan);

  // Thay thế các biến tùy chỉnh khác
  Object.keys(variableValues).forEach(key => {
    const val = variableValues[key];
    if (val !== undefined && val !== null) {
      result = result.replace(new RegExp('\\{\\{' + key + '\\}\\}', 'g'), val);
    }
  });

  return result;
}

/**
 * Tìm kiếm và lọc prompt
 */
export function searchPrompts(
  query: string,
  groupId?: number,
  categoryCode?: string,
  docType?: string
): PromptTemplate[] {
  let results = PROMPT_LIBRARY;

  if (groupId && groupId > 0) {
    results = results.filter(p => p.groupId === groupId);
  }

  if (categoryCode && categoryCode !== 'all') {
    results = results.filter(p => p.categoryCode === categoryCode);
  }

  if (docType && docType !== 'all') {
    results = results.filter(p => p.docType.toLowerCase() === docType.toLowerCase());
  }

  if (query && query.trim()) {
    const q = query.toLowerCase().trim();
    results = results.filter(p => {
      return (
        p.id.toString() === q ||
        p.title.toLowerCase().includes(q) ||
        p.task.toLowerCase().includes(q) ||
        p.tags.some(tag => tag.includes(q)) ||
        p.inputs.some(inp => inp.key.toLowerCase().includes(q) || inp.value.toLowerCase().includes(q))
      );
    });
  }

  return results;
}
